class Solution {
    struct Node {
        int next[2] = {-1, -1};
        int cnt = 0;
    };
    std::vector<Node> trie;

    void insert(int val) {
        int u = 0;
        for (int i = 30; i >= 0; --i) {
            int bit = (val >> i) & 1;
            if (trie[u].next[bit] == -1) {
                trie[u].next[bit] = trie.size();
                trie.emplace_back();
            }
            u = trie[u].next[bit];
            trie[u].cnt++;
        }
    }

    int query(int val, int limit) {
        int u = 0;
        int ans = 0;
        for (int i = 30; i >= 0; --i) {
            if (u == -1) break;
            int v_bit = (val >> i) & 1;
            int k_bit = (limit >> i) & 1;

            if (k_bit == 0) {
                int opp = 1 - v_bit;
                if (trie[u].next[opp] != -1) {
                    ans += trie[trie[u].next[opp]].cnt;
                }
                u = trie[u].next[v_bit];
            } else {
                int opp = 1 - v_bit;
                u = trie[u].next[opp];
            }
        }
        if (u != -1) ans += trie[u].cnt;
        return ans;
    }

