import java.util.*;

class Solution {
    static class Node {
        int[] next = {-1, -1};
        int cnt = 0;
    }

    private List<Node> trie = new ArrayList<>();

    public long countSubarrays(int[] nums, int k) {
        trie.clear();
        trie.add(new Node());

        insert(0);
        int curr = 0;
        long ans = 0;

        for (int x : nums) {
            curr ^= x;
            ans += query(curr, k);
            insert(curr);
        }

        return ans;
    }

    private void insert(int val) {
        int u = 0;
        for (int i = 30; i >= 0; i--) {
            int bit = (val >> i) & 1;
            if (trie.get(u).next[bit] == -1) {
                trie.get(u).next[bit] = trie.size();
                trie.add(new Node());
            }
            u = trie.get(u).next[bit];
            trie.get(u).cnt++;
        }
    }

    private int query(int val, int limit) {
        int u = 0;
        int ans = 0;
        for (int i = 30; i >= 0; i--) {
            if (u == -1) break;
            int vBit = (val >> i) & 1;
            int kBit = (limit >> i) & 1;

            if (kBit == 0) {
                int opp = 1 - vBit;
                int childOpp = trie.get(u).next[opp];
                if (childOpp != -1) {
                    ans += trie.get(childOpp).cnt;
                }
                u = trie.get(u).next[vBit];
            } else {
                int opp = 1 - vBit;
                u = trie.get(u).next[opp];
            }
        }
        if (u != -1) ans += trie.get(u).cnt;
        return ans;
    }
}

