var countSubarrays = function(nums, k) {
    const trie = [{ next: [-1, -1], cnt: 0 }];

    const insert = (val) => {
        let u = 0;
        for (let i = 30; i >= 0; i--) {
            const bit = (val >> i) & 1;
            if (trie[u].next[bit] === -1) {
                trie[u].next[bit] = trie.length;
                trie.push({ next: [-1, -1], cnt: 0 });
            }
            u = trie[u].next[bit];
            trie[u].cnt++;
        }
    };

    const query = (val, limit) => {
        let u = 0;
        let ans = 0;
        for (let i = 30; i >= 0; i--) {
            if (u === -1) break;
            const vBit = (val >> i) & 1;
            const kBit = (limit >> i) & 1;

            if (kBit === 0) {
                const opp = 1 - vBit;
                const childOpp = trie[u].next[opp];
                if (childOpp !== -1) {
                    ans += trie[childOpp].cnt;
                }
                u = trie[u].next[vBit];
            } else {
                const opp = 1 - vBit;
                u = trie[u].next[opp];
            }
        }
        if (u !== -1) ans += trie[u].cnt;
        return ans;
    };

    insert(0);
    let curr = 0;
    let ans = 0;

    for (const x of nums) {
        curr ^= x;
        ans += query(curr, k);
        insert(curr);
    }

    return ans;
};
